            .egl => |item| {
                raw.platform = c.MLN_OPENGL_CONTEXT_PLATFORM_EGL;
                raw.data.egl = item.toNative();
            },
            .webgl => |item| {
                raw.platform = c.MLN_OPENGL_CONTEXT_PLATFORM_WEBGL;
                raw.data.webgl = try item.toNative(allocator, roots);
